import type { Metadata } from "next";
import entriesJson from "@/content/entries.json";
import articlesJson from "@/content/ar/articles.json";
import oldTextFixes from "@/content/ar/old-text-fixes.json";
import oldEnglishFixes from "@/content/old-text-fixes-en.json";
import { improveLinks } from "@/lib/article-links";
import { AR_PATHS } from "@/content/ar/paths";
import { arPathOf, enPathOf, isolateLtrHtml } from "@/lib/i18n-data";
import { getLang } from "@/lib/i18n";

// Generated by tools/convert_content.py from the WordPress backup: do not edit entries.json by hand.
export type Entry = {
  id: number;
  kind: "page" | "service" | "post";
  lang: "en" | "ar";
  path: string;
  slug: string;
  title: string;
  date: string;
  modified: string;
  excerpt: string;
  featured: string;
  seo: { title: string; description: string; canonical: string; robots: Record<string, string> };
  html: string;
};

// Arabic text written for this site, by English path: replaces a stub, or gives an English page its first Arabic version
type ArticleOverride = { title?: string; html?: string; excerpt?: string; seoTitle?: string; seoDescription?: string };
const articles = articlesJson as Record<string, ArticleOverride>;

// English image descriptions and summaries the old Arabic posts carried, in Arabic
const fixOldText = (text: string) => Object.entries(oldTextFixes).reduce((out, [en, ar]) => out.split(en).join(ar), text);
// Broken sentences in the old English articles, fixed with Osama's OK (2026-11-12)
const fixOldEnglish = (html: string) => Object.entries(oldEnglishFixes).reduce((out, [from, to]) => out.split(from).join(to), html);

const allEntries = entriesJson as Entry[];
const englishEntries = allEntries.filter((e) => e.lang === "en").map((e) => ({ ...e, html: improveLinks(fixOldEnglish(e.html), "en", e.path) }));
const oldArabic = new Map(
  allEntries
    .filter((e) => e.lang === "ar")
    .map((e) => [decodeURI(e.path), { ...e, html: fixOldText(e.html), excerpt: fixOldText(e.excerpt), seo: { ...e.seo, description: fixOldText(e.seo.description) } }]),
);

// Every Arabic page: the old Arabic entry (address, title, SEO) under the English page's kind, plus any override
const arabicEntries: Entry[] = (() => {
  const made = englishEntries.flatMap((en): Entry[] => {
    const arPath = en.path === "/" ? "/ar/" : AR_PATHS[en.path];
    if (!arPath) return [];
    const old = oldArabic.get(arPath);
    const extra = articles[en.path] ?? {};
    const title = extra.title ?? old?.title ?? en.title;
    return [
      {
        ...(old ?? en),
        kind: en.kind,
        lang: "ar",
        path: arPath,
        slug: arPath.split("/").filter(Boolean).pop() ?? "",
        title,
        featured: old?.featured || en.featured,
        excerpt: extra.excerpt ?? old?.excerpt ?? en.excerpt,
        // old treatment articles end with their own booking block; the page already has one
        html: isolateLtrHtml(extra.html ?? (en.kind === "service" ? old?.html.replace(/<h[23][^>]*>(?:\s|<[^>]+>)*احجز[\s\S]*$/, "") : old?.html) ?? en.html),
        seo: {
          title: extra.seoTitle ?? old?.seo.title ?? title,
          description: extra.seoDescription ?? old?.seo.description ?? extra.excerpt ?? "",
          canonical: old?.seo.canonical ?? encodeURI(arPath),
          robots: old?.seo.robots ?? {},
        },
      },
    ];
  });
  const used = new Set(made.map((e) => e.path));
  const onlyArabic = [...oldArabic.values()].filter((e) => !used.has(decodeURI(e.path))).map((e) => ({ ...e, html: isolateLtrHtml(e.html), path: decodeURI(e.path), slug: decodeURI(e.path).split("/").filter(Boolean).pop() ?? "" }));
  return [...made, ...onlyArabic].map((e) => ({ ...e, html: improveLinks(e.html, "ar", e.path) })).sort((a, b) => b.date.localeCompare(a.date));
})();

/** Entries in the language of the page being rendered. */
const current = () => (getLang() === "ar" ? arabicEntries : englishEntries);

export const getByPath = (path: string) => (path.startsWith("/ar/") ? arabicEntries.find((e) => e.path === decodeURI(path)) : englishEntries.find((e) => e.path === path));

/** Old WordPress ids are the English pages' ids; on an Arabic page this returns the same page's Arabic version. */
export const getById = (id: number) => {
  const en = englishEntries.find((e) => e.id === id);
  if (getLang() !== "ar" || !en) return en ?? allEntries.find((e) => e.id === id);
  const arPath = en.path === "/" ? "/ar/" : AR_PATHS[en.path];
  return arabicEntries.find((e) => e.path === arPath) ?? en;
};

export const entriesByLang = (lang: Entry["lang"]) => (lang === "ar" ? arabicEntries : englishEntries);
export const servicesEn = () => current().filter((e) => e.kind === "service");
export const postsEn = () => current().filter((e) => e.kind === "post");

/** Addresses of a page in both languages, for hreflang. */
export function languageLinks(path: string): Record<string, string> | undefined {
  const decoded = decodeURI(path);
  const en = decoded.startsWith("/ar/") ? (decoded === "/ar/" ? "/" : enPathOf(decoded)) : decoded;
  const ar = decoded.startsWith("/ar/") ? decoded : arPathOf(decoded);
  if (!en || !ar) return undefined;
  return { en, ar: encodeURI(ar), "x-default": en };
}

/** Old SEO (Yoast) to Next.js metadata, so titles, descriptions and canonicals stay identical. */
export function seoMetadata(e: Entry): Metadata {
  const noindex = e.seo.robots?.index === "noindex";
  const description = e.seo.description || e.excerpt;
  return {
    title: e.seo.title || e.title,
    description,
    alternates: { canonical: e.seo.canonical || e.path, languages: languageLinks(e.path) },
    robots: noindex ? { index: false, follow: true } : undefined,
    openGraph: {
      title: e.seo.title || e.title,
      description,
      url: e.seo.canonical || e.path,
      type: e.kind === "post" ? "article" : "website",
      images: e.featured ? [e.featured] : ["/images/share-default.jpg"],
      locale: e.lang === "ar" ? "ar_AE" : "en_AE",
    },
  };
}

export const readingMinutes = (html: string) => Math.max(1, Math.round(html.replace(/<[^>]+>/g, " ").split(/\s+/).length / 220));

export const formatDate = (iso: string) => new Date(iso).toLocaleDateString(getLang() === "ar" ? "ar-AE" : "en-GB", { day: "numeric", month: "long", year: "numeric" });
